/* ===== Fórmulas (índices e expoentes), tabelas e imagens no texto ===== */
const SUPM={"0":"⁰","1":"¹","2":"²","3":"³","4":"⁴","5":"⁵","6":"⁶","7":"⁷","8":"⁸","9":"⁹","+":"⁺","-":"⁻","−":"⁻","=":"⁼","(":"⁽",")":"⁾","n":"ⁿ","i":"ⁱ"};
const SUBM={"0":"₀","1":"₁","2":"₂","3":"₃","4":"₄","5":"₅","6":"₆","7":"₇","8":"₈","9":"₉","+":"₊","-":"₋","−":"₋","=":"₌","(":"₍",")":"₎"};
const SUPR={},SUBR={};Object.entries(SUPM).forEach(([a,b])=>{if(!SUPR[b])SUPR[b]=a});Object.entries(SUBM).forEach(([a,b])=>{if(!SUBR[b])SUBR[b]=a});
function toSup(x){x=String(x).trim();if(!x)return "";return [...x].every(c=>SUPM[c])?[...x].map(c=>SUPM[c]).join(""):"^("+x+")"}
function toSub(x){x=String(x).trim();if(!x)return "";return [...x].every(c=>SUBM[c])?[...x].map(c=>SUBM[c]).join(""):"_("+x+")"}
const RX_FORM=/(\^\(([^()]*)\))|(\^([0-9A-Za-z+\-−]+))|(_\(([^()]*)\))|([⁰¹²³⁴⁵⁶⁷⁸⁹⁺⁻⁼⁽⁾ⁿⁱ]+)|([₀₁₂₃₄₅₆₇₈₉₊₋₌₍₎]+)/g;
function segFormula(str){const out=[];let last=0;str.replace(RX_FORM,(m,a,a1,b,b1,c,c1,d,e,off)=>{if(off>last)out.push({t:str.slice(last,off)});
  if(a)out.push({t:a1,sup:1});else if(b)out.push({t:b1,sup:1});else if(c)out.push({t:c1,sub:1});
  else if(d)out.push({t:[...d].map(x=>SUPR[x]).join(""),sup:1});else if(e)out.push({t:[...e].map(x=>SUBR[x]).join(""),sub:1});
  last=off+m.length;return m});if(last<str.length)out.push({t:str.slice(last)});return out}
function segs(str){const out=[];String(str).split(/(\*\*.+?\*\*|\[(?:INSERIR|IMAGEM)[^\]]*\])/gi).forEach(x=>{if(!x)return;
  if(/^\*\*.+\*\*$/.test(x))segFormula(x.slice(2,-2)).forEach(y=>out.push({...y,b:1}));
  else if(/^\[(INSERIR|IMAGEM)/i.test(x))out.push({t:x,red:1,b:1});
  else segFormula(x).forEach(y=>out.push(y))});return out}
function md(str){return segs(str).map(x=>{let h=esc(x.t);if(x.sup)h="<sup>"+h+"</sup>";if(x.sub)h="<sub>"+h+"</sub>";if(x.b)h="<b>"+h+"</b>";if(x.red)h='<span class="fill">'+h+"</span>";return h}).join("")}
const temFormula=t=>/[=¹²³⁰-⁹₀-₉√∑∫πΔ∆→⇌±×÷≤≥≠≈λμΩ]|\^\(|_\(|\b[A-Z][a-z]?\d+\b/.test(String(t).replace(/\[\[IMG:[^\]]+\]\]/g,""));
const RX_TOKEN=/\[\[IMG:([\w-]+)\]\]/g;
const idsImg=t=>[...String(t||"").matchAll(RX_TOKEN)].map(m=>m[1]);
function blocos(t){const out=[];String(t||"").split("\n").forEach(l=>{
  const im=l.trim().match(/^\[\[IMG:([\w-]+)\]\]$/);if(im){out.push({k:"img",id:im[1]});return}
  if(/^\s*\|.*\|\s*$/.test(l)){const cells=l.trim().slice(1,-1).split("|").map(c=>c.trim());if(cells.every(c=>/^:?-{2,}:?$/.test(c)))return;
    const last=out[out.length-1];if(last&&last.k==="tab")last.rows.push(cells);else out.push({k:"tab",rows:[cells]});return}
  const last=out[out.length-1];if(last&&last.k==="txt")last.lines.push(l);else out.push({k:"txt",lines:[l]})});return out}
function linearizar(rows){if(rows.length<2)return rows.map(r=>r.join("; ")).join("\n");const h=rows[0];
  return ["Tabela com "+(rows.length-1)+" linha(s) e "+h.length+" coluna(s). Colunas: "+h.join(", ")+".",...rows.slice(1).map((r,i)=>"Linha "+(i+1)+": "+r.map((c,j)=>(h[j]||"Coluna "+(j+1))+": "+c).join("; ")+".")].join("\n")}
/* visualização do texto (original e prévia) */
function blocosHTML(t,prefix,modo){const f=S.fmt;const bs=blocos(t);let h="",first=true;const prova=modo==="prova";
  if(prefix&&bs.length&&bs[0].k!=="txt"){h+=`<p>${prefix}</p>`;first=false}
  bs.forEach(b=>{if(b.k==="txt"){b.lines.forEach(l=>{h+=`<p>${first&&prefix?prefix+" ":""}${md(l)||"&nbsp;"}</p>`;first=false})}
    else if(b.k==="tab"){h+=(prova&&f.tabelaLinear)?linearizar(b.rows).split("\n").map(l=>`<p>${md(l)}</p>`).join(""):`<table class="ptab">${b.rows.map((r,i)=>`<tr>${r.map(c=>i?`<td>${md(c)}</td>`:`<th>${md(c)}</th>`).join("")}</tr>`).join("")}</table>`;first=false}
    else{const im=S.imgs[b.id];
      if(im&&im.data)h+=prova?`<figure class="pfig"><img src="${im.data}" alt="${esc(im.desc||"")}" style="width:${Math.min(100,Math.round(Math.min(im.w,420)*(f.ampliarImg||1)/6.4))}%"></figure>`:`<img src="${im.data}" alt="">`;
      else h+=`<p class="fill">[INSERIR IMAGEM DA QUESTÃO ORIGINAL]</p>`;
      if(prova&&im&&im.desc&&f.descNaProva)h+=`<p><i><b>Descrição da imagem:</b> ${esc(im.desc).replace(/\n/g,"<br>")}</i></p>`;first=false}});
  return h}

/* ===== Imagens ===== */
const imgId=()=>"i"+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
function normalizarImagem(src){return new Promise(res=>{const im=new Image();im.onload=()=>{let w=im.naturalWidth,h=im.naturalHeight;if(!w||!h)return res(null);const k=Math.min(1,1400/Math.max(w,h));w=Math.round(w*k);h=Math.round(h*k);
  const c=document.createElement("canvas");c.width=w;c.height=h;const x=c.getContext("2d");x.fillStyle="#fff";x.fillRect(0,0,w,h);x.drawImage(im,0,0,w,h);
  let d=c.toDataURL("image/png"),ext="png";if(d.length>700000){d=c.toDataURL("image/jpeg",.88);ext="jpg"}res({data:d,w,h,ext})};im.onerror=()=>res(null);im.src=src})}
async function registrarImagem(src,desc){const n=src?await normalizarImagem(src):null;const id=imgId();S.imgs[id]=n?{...n,desc:desc||""}:{data:"",w:0,h:0,ext:"",desc:desc||"",invalida:true};return id}
function lerArquivoURL(file){return new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)})}
function dataBlob(d){const [h,b]=d.split(",");return new Blob([b64buf(b)],{type:(h.match(/data:([^;]+)/)||[])[1]||"image/png"})}

/* ===== Importação: Word (com equações), PDF e texto ===== */
const MNS="http://schemas.openxmlformats.org/officeDocument/2006/math",WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main";
function ommlTexto(n){if(!n)return "";const kids=[...n.childNodes].filter(c=>c.nodeType===1);const ch=nm=>kids.find(c=>c.localName===nm);const L=ommlTexto;
  const val=(pr,nm,def)=>{if(!pr)return def;const e=[...pr.getElementsByTagNameNS(MNS,nm)][0];if(!e)return def;const v=e.getAttributeNS(MNS,"val")||e.getAttribute("m:val");return v==null?def:v};
  const par=x=>x.length>1&&/[+\-−=*·× ]/.test(x)?"("+x+")":x;
  switch(n.localName){
   case "t":return n.textContent;
   case "r":return kids.filter(c=>c.localName==="t").map(c=>c.textContent).join("");
   case "f":return par(L(ch("num")))+"/"+par(L(ch("den")));
   case "sSup":return L(ch("e"))+toSup(L(ch("sup")));
   case "sSub":return L(ch("e"))+toSub(L(ch("sub")));
   case "sSubSup":return L(ch("e"))+toSub(L(ch("sub")))+toSup(L(ch("sup")));
   case "sPre":return toSub(L(ch("sub")))+toSup(L(ch("sup")))+L(ch("e"));
   case "rad":{const d=L(ch("deg"));return (d?toSup(d):"")+"√("+L(ch("e"))+")"}
   case "d":{const pr=ch("dPr");const b=val(pr,"begChr","("),e=val(pr,"endChr",")"),sp=val(pr,"sepChr","|");return b+kids.filter(c=>c.localName==="e").map(L).join(sp==="|"?" | ":sp+" ")+e}
   case "nary":{const pr=ch("naryPr");const c=val(pr,"chr","∫");const lo=L(ch("sub")),hi=L(ch("sup"));return c+(lo?"_("+lo+")":"")+(hi?"^("+hi+")":"")+" "+L(ch("e"))}
   case "func":return L(ch("fName"))+" "+L(ch("e"));
   case "limLow":return L(ch("e"))+"_("+L(ch("lim"))+")";
   case "limUpp":return L(ch("e"))+"^("+L(ch("lim"))+")";
   case "acc":return L(ch("e"))+val(ch("accPr"),"chr","\u0302");
   case "bar":return L(ch("e"))+"\u0305";
   case "eqArr":return kids.filter(c=>c.localName==="e").map(L).join("; ");
   case "m":return "["+kids.filter(c=>c.localName==="mr").map(r=>[...r.childNodes].filter(c=>c.localName==="e").map(L).join(" ")).join("; ")+"]";
   default:return kids.filter(c=>!/Pr$/.test(c.localName)).map(L).join("")}}
async function prepararDocx(buf){
  const zip=await JSZip.loadAsync(buf);const f=zip.file("word/document.xml");if(!f)return {buf,n:0};const xml=await f.async("string");
  if(!/<m:oMath/.test(xml))return {buf,n:0};
  const doc=new DOMParser().parseFromString(xml,"application/xml");let n=0;
  const mk=t=>{const r=doc.createElementNS(WNS,"w:r");const tt=doc.createElementNS(WNS,"w:t");tt.setAttributeNS("http://www.w3.org/XML/1998/namespace","xml:space","preserve");tt.textContent=t;r.appendChild(tt);return r};
  const troca=(el,t)=>{let node=mk(t);if(el.parentNode.localName==="body"){const pp=doc.createElementNS(WNS,"w:p");pp.appendChild(node);node=pp}el.parentNode.replaceChild(node,el);n++};
  [...doc.getElementsByTagNameNS(MNS,"oMathPara")].forEach(el=>troca(el,[...el.getElementsByTagNameNS(MNS,"oMath")].map(ommlTexto).join("   ")));
  [...doc.getElementsByTagNameNS(MNS,"oMath")].forEach(el=>troca(el," "+ommlTexto(el)+" "));
  zip.file("word/document.xml",new XMLSerializer().serializeToString(doc));
  return {buf:await zip.generateAsync({type:"arraybuffer"}),n};
}
async function htmlParaTexto(html){
  const doc=new DOMParser().parseFromString("<div id='r'>"+html+"</div>","text/html");const out=[],pend=[];let topNum=0;
  const inline=node=>{let r="";node.childNodes.forEach(n=>{if(n.nodeType===3){r+=n.textContent;return}if(n.nodeType!==1)return;const t=n.tagName;
    if(t==="IMG"){pend.push(n.getAttribute("src"));r+="\n[[IMGP:"+(pend.length-1)+"]]\n"}
    else if(t==="SUP")r+=toSup(inline(n));else if(t==="SUB")r+=toSub(inline(n));
    else if(t==="STRONG"||t==="B"){const x=inline(n);r+=(x.trim()&&!/\[\[IMGP/.test(x))?"**"+x.trim()+"** ":x}
    else if(t==="BR")r+="\n";else if(t==="TABLE"||t==="OL"||t==="UL"){}else r+=inline(n)});return r};
  const walk=(el,depth)=>{el.childNodes.forEach(n=>{if(n.nodeType!==1){const t=(n.textContent||"").trim();if(t)out.push(t);return}const t=n.tagName;
    if(/^(P|H[1-6])$/.test(t))out.push(inline(n));
    else if(t==="TABLE"){n.querySelectorAll("tr").forEach(tr=>{const cs=[...tr.children].map(td=>{const x=inline(td);return x.replace(/\[\[IMGP:\d+\]\]/g,"[imagem na tabela]").replace(/\s*\n\s*/g," ").replace(/\|/g,"/").trim()});out.push("| "+cs.join(" | ")+" |")});
      n.querySelectorAll("img").forEach(im=>{pend.push(im.getAttribute("src"));out.push("[[IMGP:"+(pend.length-1)+"]]")})}
    else if(t==="OL"||t==="UL"){let k=0;[...n.children].forEach(li=>{if(li.tagName!=="LI")return;let pre="";
        if(t==="OL"){if(depth===0){topNum++;pre=topNum+". "}else pre=letra(k)+") "}else pre=depth?"• ":"";k++;
        const own=document.createElement("div");[...li.childNodes].forEach(c=>{if(!(c.nodeType===1&&/^(OL|UL)$/.test(c.tagName)))own.appendChild(c.cloneNode(true))});
        out.push(pre+inline(own).trim());[...li.children].filter(c=>/^(OL|UL)$/.test(c.tagName)).forEach(sub=>{const d=document.createElement("div");d.appendChild(sub.cloneNode(true));walk(d,depth+1)})})}
    else walk(n,depth)})};
  walk(doc.getElementById("r"),0);
  const ids=[];for(const src of pend)ids.push(await registrarImagem(src));
  return out.join("\n").replace(/\[\[IMGP:(\d+)\]\]/g,(m,k)=>"[[IMG:"+ids[+k]+"]]").split("\n").map(l=>l.replace(/\s+$/,"").replace(/^\s+(?=\[\[IMG)/,"")).join("\n").replace(/\n{3,}/g,"\n\n").trim();
}
async function lerDocx(buf){const prep=await prepararDocx(buf);
  const r=await mammoth.convertToHtml({arrayBuffer:prep.buf},{convertImage:mammoth.images.imgElement(img=>img.read("base64").then(b=>({src:"data:"+img.contentType+";base64,"+b})))});
  return {texto:await htmlParaTexto(r.value),eq:prep.n}}
async function lerPdf(buf){
  const lib=globalThis.pdfjsLib;if(!lib)throw new Error("pdf indisponível");
  const pdf=await lib.getDocument({data:new Uint8Array(buf),isEvalSupported:false}).promise;const out=[];
  for(let pn=1;pn<=pdf.numPages;pn++){const pg=await pdf.getPage(pn);const tc=await pg.getTextContent();
    const it=tc.items.filter(i=>i.str&&i.str.length).map(i=>({s:i.str,x:i.transform[4],y:i.transform[5],h:Math.abs(i.transform[3])||i.height||10,w:i.width||0}));
    it.sort((a,b)=>b.y-a.y||a.x-b.x);const lines=[];
    for(const i of it){let L=lines.find(l=>Math.abs(l.y-i.y)<Math.max(2,Math.min(l.h,i.h)*0.6));if(!L){L={y:i.y,h:i.h,items:[]};lines.push(L)}L.items.push(i);if(i.h>L.h){L.h=i.h;L.y=i.y}}
    lines.sort((a,b)=>b.y-a.y);
    for(const L of lines){L.items.sort((a,b)=>a.x-b.x);let st="",px=null;
      for(const i of L.items){let t=i.s;const tt=t.trim();const small=i.h<L.h*0.8&&/^[0-9+\-−n]+$/.test(tt);
        if(small)t=i.y>L.y+L.h*0.15?toSup(tt):(i.y<L.y-L.h*0.05?toSub(tt):t);
        if(px!==null&&!small&&i.x-px>L.h*0.2&&!st.endsWith(" ")&&!t.startsWith(" "))st+=" ";st+=t;px=i.x+i.w}
      out.push(st.trim())}
    out.push("")}
  return out.join("\n").replace(/\n{3,}/g,"\n\n").trim();
}

/* ================= Leitura da prova ================= */
const RX_Q=/^\s*(?:quest[ãa]o\s*)?(\d{1,2})\s*(?:[.)\-–:º°]|\s-\s)\s*(.*)$/i;
const RX_QW=/^\s*quest[ãa]o\s*(\d{1,2})\s*[:.\-–]?\s*(.*)$/i;
const RX_ALT=/^\s*\(?([a-eA-E])\s*[).\-–]\s+(.*)$/;
function splitInlineAlts(line){
  // "a) x  b) y  c) z" na mesma linha
  const m=line.match(/(^|\s)\(?([a-e])\)\s/gi);
  if(!m||m.length<2)return [line];
  return line.split(/\s(?=\(?[b-e]\)\s)/i);
}
function parseProva(txt){
  const lines=txt.replace(/\r/g,"").split("\n");
  const qs=[];let pre=[];let cur=null;let lastWasAlt=false;
  for(let raw of lines){
    const parts=splitInlineAlts(raw);
    for(const line of parts){
      const mq=line.match(RX_QW)||line.match(RX_Q);
      const ma=line.match(RX_ALT);
      if(mq && !(cur&&ma&&!/^\s*\d/.test(line))){
        cur={id:nid(),num:+mq[1],enunciado:(mq[2]||"").trim(),alternativas:[],correta:null,incluir:true,adapt:null};
        qs.push(cur);lastWasAlt=false;continue;
      }
      if(cur&&ma){cur.alternativas.push({texto:ma[2].trim(),manter:true});lastWasAlt=true;continue}
      if(!cur){pre.push(line);continue}
      if(/^\s*\[\[IMG:/.test(line)||/^\s*\|.*\|\s*$/.test(line)){if(cur&&lastWasAlt){cur.enunciado+="\n"+line.trim();continue}}
      if(lastWasAlt&&line.trim()&&cur.alternativas.length&&!/^\s*\[\[IMG:/.test(line)){cur.alternativas[cur.alternativas.length-1].texto+=" "+line.trim();continue}
      cur.enunciado+=(cur.enunciado?"\n":"")+line;
    }
  }
  qs.forEach(q=>q.enunciado=q.enunciado.replace(/\n{3,}/g,"\n\n").trim());
  return {instrucoes:pre.join("\n").trim(),questoes:qs};
}

/* ================= Diagnóstico ================= */
function comandos(t){const low=t.toLowerCase();return VERBOS.filter(v=>new RegExp("\\b"+v+"\\b").test(low))}
function diag(q,tipo){
  const out=[];const t=q.enunciado||"";const w=words(t);
  if(w>90)out.push({k:"warn",t:`Enunciado longo (${w} palavras)`});
  const nq=(t.match(/\?/g)||[]).length;const cv=comandos(t);
  if(nq>1||cv.length>1)out.push({k:"warn",t:"Mais de um comando"});
  if(/\b(n[ãa]o|exceto|incorret[ao]s?|fals[ao]s?)\b/i.test(t))out.push({k:"warn",t:"Comando negativo"});
  const ims=idsImg(t);
  if(ims.length){const sem=ims.filter(id=>!(S.imgs[id]&&S.imgs[id].desc)).length;out.push({k:"info",t:ims.length+" imagem(ns)"});if(sem&&S.barreiras.includes("visao"))out.push({k:"crit",t:sem+" sem descrição"});if(ims.some(id=>S.imgs[id]&&S.imgs[id].invalida))out.push({k:"crit",t:"Imagem não importada"})}
  else if(/\b(imagem|figura|gr[áa]fico|mapa|charge|tirinha|ilustra[çc][ãa]o|foto(grafia)?|quadrinhos?|esquema)\b/i.test(t))out.push({k:"warn",t:"Cita imagem não anexada"});
  if(blocos(t).some(b=>b.k==="tab"))out.push({k:"info",t:"Tabela"});
  if(temFormula(t))out.push({k:"info",t:"Fórmulas/símbolos"});
  if(q.alternativas.length){
    out.push({k:"info",t:`Objetiva · ${q.alternativas.length} alternativas`});
    if(tipo>=3&&q.alternativas.length>3)out.push({k:"crit",t:"Reduzir alternativas"});
    if(tipo>=3&&q.correta==null)out.push({k:"warn",t:"Marque a correta"});
  } else {
    out.push({k:"info",t:"Discursiva"});
    if(tipo>=3)out.push({k:"warn",t:"Tipo 3: preferir objetiva ou resposta no texto"});
  }
  return out;
}

/* ================= Regras automáticas ================= */
function destacar(t,fmt){
  let s=t;
  if(fmt.destacarNegacao)s=s.replace(/(^|[^*\wÀ-ú])(n[ãa]o|exceto|incorret[ao]s?|fals[ao]s?)(?=[^\wÀ-ú]|$)/gi,(m,a,w)=>a+"**"+w.toUpperCase()+"**");
  if(fmt.destacarComando){
    const re=new RegExp("(^|[^*\\wÀ-ú])("+VERBOS.join("|")+")(?=[^\\wÀ-ú]|$)","gi");
    s=s.replace(re,(m,a,w)=>a+"**"+w+"**");
  }
  return s.replace(/\*\*\*\*/g,"");
}
function dividirComandos(t){
  // separa perguntas múltiplas em itens a), b) (somente discursivas)
  const paras=t.split(/\n/);const last=paras.pop();
  if(!last||/^\s*(\||\[\[IMG)/.test(last))return null;
  const sent=last.split(/(?<=[.?!])\s+/);
  const perg=sent.filter(s=>/\?\s*$/.test(s));
  if(perg.length<2)return null;
  const ctx=sent.filter(s=>!/\?\s*$/.test(s)).join(" ").trim();
  const itens=perg.map((p,i)=>`${letra(i)}) ${p.trim()}`).join("\n");
  return [...paras,ctx,itens].filter(Boolean).join("\n");
}
function aplicarRegras(q){
  const tipo=S.tipo,fmt=S.fmt;
  const a={enunciado:q.enunciado,alternativas:q.alternativas.map(x=>x.texto),correta:q.correta,glossario:(q.adapt&&q.adapt.glossario)||[],descImagem:(q.adapt&&q.adapt.descImagem)||"",obs:[],origem:"regras",linhas:q.alternativas.length?0:fmt.linhas};
  if(tipo>=2&&!q.alternativas.length){const d=dividirComandos(a.enunciado);if(d){a.enunciado=d;a.obs.push("Perguntas separadas em itens (um comando por item).")}}
  if(tipo>=3&&q.alternativas.length>3){
    if(q.correta!=null){
      const keep=[q.correta];for(let i=0;i<q.alternativas.length&&keep.length<3;i++)if(i!==q.correta)keep.push(i);
      keep.sort((x,y)=>x-y);a.alternativas=keep.map(i=>q.alternativas[i].texto);a.correta=keep.indexOf(q.correta);
      a.obs.push("Alternativas reduzidas para 3 (correta + 2 distratores). Confira se os distratores mantidos são os mais adequados.");
    } else a.obs.push("Não foi possível reduzir as alternativas: marque a correta na etapa Questões.");
  }
  if(tipo>=3&&!q.alternativas.length)a.obs.push("Tipo 3: avaliar conversão para objetiva ou indicar no texto onde está a resposta.");
  if(tipo>=2&&words(a.enunciado)>90)a.obs.push("Texto longo: considere reduzir ou dividir.");
  if(!idsImg(q.enunciado).length&&/\b(imagem|figura|gr[áa]fico|mapa|charge|tirinha|ilustra[çc][ãa]o|esquema)\b/i.test(q.enunciado)&&!a.descImagem&&S.barreiras.includes("visao"))a.obs.push("O enunciado cita uma imagem que não está anexada: anexe a imagem ou escreva a descrição complementar.");
  if(temFormula(q.enunciado)||q.alternativas.some(x=>temFormula(x.texto)))a.obs.push("Contém fórmulas ou símbolos: confira índices, expoentes e unidades.");
  const sem=idsImg(q.enunciado).filter(id=>!(S.imgs[id]&&S.imgs[id].desc));
  if(sem.length&&S.barreiras.includes("visao"))a.obs.push("Há "+sem.length+" imagem(ns) sem descrição: use “Descrever com IA” ou escreva a descrição.");
  if(S.fmt.visao==="cegueira"&&/\b(observe|veja|olhe)\b/i.test(q.enunciado))a.obs.push("Estudante cego: substitua “observe a figura” por “leia a descrição da imagem”.");
  a.enunciado=a.enunciado.split("\n").map(l=>/^\s*(\||\[\[IMG)/.test(l)?l:destacar(l,fmt)).join("\n");a.alternativas=a.alternativas.map(x=>x);
  return a;
}

